import fs from 'node:fs';
import path from 'node:path';
const root = process.cwd(), out = path.join(root, 'public/training');
const files = ['main.tsx', 'App.tsx', 'useProjectModel.ts', 'domain.ts', 'organization.ts', 'pages/GridPage.tsx', 'pages/FormPage.tsx', 'pages/ChartsPage.tsx', 'pages/TreePage.tsx', 'pages/PivotPage.tsx', 'pages/GuidePage.tsx', 'components/ErrorBoundary.tsx', 'api/projects.ts', 'server/mockApi.ts', 'vite.config.ts'];
const sourcePath = file => file.startsWith('server/') || file === 'vite.config.ts' ? path.join(root, file) : path.join(root, 'src', file);
const sourceLabel = file => file.startsWith('server/') || file === 'vite.config.ts' ? file : 'src/' + file;
const sourceName = file => `source-${file.replaceAll('/', '--')}.html`;
for (const file of fs.readdirSync(out)) if (file.startsWith('source-') && file.endsWith('.html')) fs.unlinkSync(path.join(out,file));
const sources = Object.fromEntries(files.map(f => [f, fs.readFileSync(sourcePath(f),'utf8').split('\n')]));
const esc = s => String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function snippet(file, start, end, description) {
 const lines=sources[file], a=lines.findIndex(l=>l.includes(start));
 if(a<0) throw Error(`Missing source marker: ${file} ${start}`);
 const b=typeof end==='number'?Math.min(a+end,lines.length):lines.findIndex((l,i)=>i>a&&l.includes(end));
 if(b<=a) throw Error(`Missing end marker: ${file} ${end}`);
 return {file,a:a+1,b,lines:lines.slice(a,b),description};
}
const S=snippet;
